/**
 * Upload a media attachment for a draft.
 *
 *   POST /api/drafts/:id/media
 *     multipart/form-data:
 *       file        binary blob (required)
 *       kind        'photo' | 'audio' | 'video'  (required)
 *       attachmentId  uuid generated by the phone (required)
 *       caption     optional string
 *       durationMs  optional number (for audio/video)
 *
 *   Returns the updated draft with the attachment appended.
 *
 * Routing logic:
 *   - photo → Cloudflare Images, attachment stores `imageId`
 *   - audio/video → R2 under drafts/<id>/<attachmentId>.<ext>, attachment
 *     stores `r2Key`; clients fetch via /api/drafts/:id/media/:attachmentId
 */

import { json } from '@sveltejs/kit';
import { getDraft, addAttachment, patchAttachment } from '#lib/server/drafts.js';
import { uploadImage } from '#lib/server/images.js';
import { putObject, draftMediaKey, extFromMime } from '#lib/server/objects.js';
import { imageUrl } from '#lib/image.js';
import { isCaptureRequest, corsHeaders, unauthorized } from '#lib/server/auth-token.js';

/** @type {import('./$types').RequestHandler} */
export async function OPTIONS({ request }) {
	return new Response(null, { status: 204, headers: corsHeaders(request) });
}

/** @type {import('./$types').RequestHandler} */
export async function POST({ request, params, locals, url }) {
	const cors = corsHeaders(request);
	if (!locals.isAdmin && !isCaptureRequest(request)) return unauthorized(request);


	const existing = await getDraft(params.id);
	if (!existing) {
		return new Response(JSON.stringify({ error: 'draft_not_found' }), {
			status: 404,
			headers: { 'content-type': 'application/json', ...cors }
		});
	}

	let form;
	try {
		form = await request.formData();
	} catch {
		return new Response(JSON.stringify({ error: 'invalid_form' }), {
			status: 400,
			headers: { 'content-type': 'application/json', ...cors }
		});
	}

	const file = form.get('file');
	const kind = String(form.get('kind') || '');
	const attachmentId = String(form.get('attachmentId') || '');
	const caption = form.get('caption') ? String(form.get('caption')) : undefined;
	const durationMs = form.get('durationMs') ? Number(form.get('durationMs')) : undefined;
	// 'main' (default) is the photo/audio/video itself. 'annotation' is the
	// AstroBin-style plate-solved star map that gets patched onto an existing
	// photo attachment instead of creating a new one.
	const slot = form.get('slot') ? String(form.get('slot')) : 'main';

	if (!(file instanceof Blob) || !kind || !attachmentId) {
		return new Response(JSON.stringify({ error: 'missing_fields', need: ['file', 'kind', 'attachmentId'] }), {
			status: 400,
			headers: { 'content-type': 'application/json', ...cors }
		});
	}

	const now = new Date().toISOString();

	try {
		if (kind === 'photo') {
			const uploaded = await uploadImage(file, {
				filename: slot === 'annotation' ? `${attachmentId}-annotation.png` : `${attachmentId}.jpg`
			});
			// Absolute, so the phone can load them from anywhere.
			const publicUrl = `${url.origin}${imageUrl(uploaded.id, { variant: 'public' })}`;
			const thumbUrl = `${url.origin}${imageUrl(uploaded.id, { w: 480, q: 85 })}`;

			// Star map: patch it onto the existing photo attachment. The client
			// always uploads the main photo first, so the row exists by now.
			if (slot === 'annotation') {
				const target = existing.attachments.find((a) => a.id === attachmentId);
				if (!target) {
					return new Response(
						JSON.stringify({ error: 'attachment_not_found', attachmentId }),
						{ status: 409, headers: { 'content-type': 'application/json', ...cors } }
					);
				}
				const next = await patchAttachment(params.id, attachmentId, {
					annotationImageId: uploaded.id,
					annotationPublicUrl: publicUrl,
					annotationThumbUrl: thumbUrl
				});
				return json({ draft: next }, { headers: cors });
			}

			const next = await addAttachment(params.id, {
				id: attachmentId,
				kind: 'photo',
				imageId: uploaded.id,
				publicUrl,
				thumbUrl,
				caption,
				createdAt: now
			});
			return json({ draft: next }, { headers: cors });
		}

		if (kind === 'audio' || kind === 'video') {
			const mime = file.type || (kind === 'audio' ? 'audio/webm' : 'video/mp4');
			const key = draftMediaKey(params.id, attachmentId, extFromMime(mime));
			await putObject(key, file);

			const attachment = {
				id: attachmentId,
				kind,
				r2Key: key,
				mimeType: mime,
				durationMs,
				caption,
				createdAt: now
			};
			const next = await addAttachment(params.id, /** @type {any} */ (attachment));
			return json({ draft: next }, { headers: cors });
		}

		return new Response(JSON.stringify({ error: 'unknown_kind', kind }), {
			status: 400,
			headers: { 'content-type': 'application/json', ...cors }
		});
	} catch (err) {
		// Surface the real error in the response body instead of letting the
		// Workers runtime swallow it as a generic 500. Personal-use app, so
		// leaking the error message to the client is acceptable; if this
		// ever serves untrusted users, strip details before returning.
		const message = err instanceof Error ? err.message : String(err);
		const stack = err instanceof Error ? (err.stack || '') : '';
		console.error('Media upload failed:', message, stack);
		return new Response(
			JSON.stringify({
				error: 'upload_failed',
				kind,
				attachmentId,
				message,
				stack: stack.split('\n').slice(0, 5).join('\n')
			}),
			{
				status: 500,
				headers: { 'content-type': 'application/json', ...cors }
			}
		);
	}
}
